import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int p = scanner.nextInt();
        int k = scanner.nextInt();
        long mod = 1000000007L;

        if (k == 0) {
            System.out.println(powMod(p, p - 1, mod));
        } else if (k == 1) {
            System.out.println(powMod(p, p, mod));
        } else {
            int ord_k = 1;
            long k_pow_ord = k % p;
            while (k_pow_ord != 1) {
                ord_k++;
                k_pow_ord = (k * k_pow_ord) % p;
            }
            long comps = (p - 1) / ord_k;
            System.out.println(powMod(p, comps, mod));
        }
        scanner.close();
    }

    private static long powMod(long base, long exp, long mod) {
        long result = 1L;
        long b = base % mod;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * b) % mod;
            }
            b = (b * b) % mod;
            e >>= 1;
        }
        return result;
    }
}
